import json,hashlib,copy,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
BASE=ROOT/'scripts/audit/baselines/s147'
# S329 / CL-P1-040 — narrow UTF-8/POSIX-path/newline normalization, same pattern as S146's fix.
S146_HASHES=json.loads((ROOT/'SESSION146_LESSON_HASHES.json').read_text(encoding='utf-8'))['files']
TARGETS={
'bv-02-03':ROOT/'content/courses/bivariate-statistics/lessons/bv-02-03.json',
'fg-03-02':ROOT/'content/courses/functions-g8/lessons/fg-03-02.json',
'fg-03-03':ROOT/'content/courses/functions-g8/lessons/fg-03-03.json',
'les-04-02':ROOT/'content/courses/linear-equations-systems/lessons/les-04-02.json',
'les-04-03':ROOT/'content/courses/linear-equations-systems/lessons/les-04-03.json',
}
def near(a,b,t=1e-9):return abs(a-b)<=t
def truth(w):
 lines=w['lines'];target=next((l for l in lines if l['id']==w.get('targetLineId')),lines[0]);stages=[];n=None;claim=None;point=None
 for l in lines:stages += [f"line:{l['id']}:slope",f"line:{l['id']}:intercept"]
 def winner(field,goal='greater'):
  vals=[l[field] for l in lines];ext=min(vals) if goal=='lower' else max(vals);wins=[l for l in lines if near(l[field],ext)];return wins[0]['id'] if len(wins)==1 else 'tie'
 task=w['task']
 if task=='readSlope':n=target['m']
 elif task=='readIntercept':n=target['b']
 elif task=='evaluateAtX':n=target['m']*w['targetInput']+target['b'];stages += [f"evaluate:{target['id']}:substitute",f"evaluate:{target['id']}:value"]
 elif task=='slopeAssociation':claim='association:'+('positive' if target['m']>0 else 'negative' if target['m']<0 else 'none')
 elif task=='compareStart':claim='start:higher:'+winner('b');stages.append('compare:starts')
 elif task=='compareRate':
  goal=w.get('rateGoal','greater');claim=f"rate:{goal}:{winner('m',goal)}";stages.append('compare:rates')
 elif task=='compareRateAndStart':claim=f"compare:rate:{winner('m')}:start:{winner('b')}";stages += ['compare:rates','compare:starts']
 elif task in ('intersectionX','intersectionY','intersectionPoint'):
  a,b=lines[:2];assert not near(a['m'],b['m']);x=(b['b']-a['b'])/(a['m']-b['m']);y=a['m']*x+a['b'];stages += ['intersection:equate','intersection:x','intersection:y','intersection:verify']
  if task=='intersectionX':n=x
  elif task=='intersectionY':n=y
  else:point=[x,y]
 elif task=='verifyPoint':
  x,y=w['candidatePoint'];ok=all(near(l['m']*x+l['b'],y) for l in lines);claim='point:yes' if ok else 'point:no';stages += [f"verify:{l['id']}" for l in lines]
 elif task=='exploreParameters':pass
 else:raise AssertionError(task)
 return {'number':n,'claim':claim,'point':point,'stages':stages}
def surfaces(doc):
 rows=[]
 for s in doc['steps']:
  if 'widget' in s:rows.append(('main',s['id'],s,s['widget']))
 for r in doc['remedials']:
  c=r['check'];rows.append(('remedial',c['id'],c,c['widget']))
 return rows
def old_answer(w):
 if w['type']=='numeric':return ('numeric',w['answer'])
 if w['type']=='mcq':
  c=[o for o in w['options'] if o.get('correct')];assert len(c)==1;return ('choice',c[0])
 if w['type']=='pointEntry':return ('point',w['answer'])
 if w['type']=='steppedReveal':return ('explore',None)
 raise AssertionError(w['type'])
errors=[];records=[];main=remedial=0
for lid,path in TARGETS.items():
 before=json.loads((BASE/f'{lid}.json').read_text(encoding='utf-8'));after=json.loads(path.read_text(encoding='utf-8'));bs=surfaces(before);as_=surfaces(after)
 if [(k,i) for k,i,_,_ in bs]!=[(k,i) for k,i,_,_ in as_]:errors.append(f'{lid}: surface order/id drift')
 for (kind,sid,bstep,bw),(_,_,astep,w) in zip(bs,as_):
  if w.get('type')!='affineRelationshipLab':errors.append(f'{lid}/{sid}: fallback {w.get("type")}');continue
  if bw['prompt']!=w['prompt']:errors.append(f'{lid}/{sid}: prompt changed')
  if bstep.get('variant')!=astep.get('variant'):errors.append(f'{lid}/{sid}: variant changed')
  t=truth(w);mode,expected=old_answer(bw);pres=False
  if mode=='numeric':pres=t['number'] is not None and near(t['number'],expected,w.get('tolerance',0)) and w['numericErrors']==bw.get('commonErrors',[])
  elif mode=='choice':
   wins=[c for c in w['choices'] if c['claim']==t['claim']];pres=len(wins)==1 and wins[0]['id']==expected['id'] and [(x['id'],x['label'],x['feedback']) for x in w['choices']]==[(x['id'],x['label'],x['feedback']) for x in bw['options']]
  elif mode=='point':pres=t['point'] is not None and all(near(a,b,w.get('tolerance',0)) for a,b in zip(t['point'],expected)) and w['pointErrors']==bw.get('commonEntries',[])
  else:pres=w['authoredStages']==bw['panels'] and w['successFeedback']==bw['successFeedback']
  if not pres:errors.append(f'{lid}/{sid}: authored answer or misconception route not preserved')
  if w['requiredExplorations']>len(t['stages']):errors.append(f'{lid}/{sid}: impossible exploration')
  if any(k not in t['stages'] for k in w.get('requiredStageKeys',[])):errors.append(f'{lid}/{sid}: invalid required stage')
  if kind=='main':main+=1
  else:remedial+=1
  records.append({'lessonId':lid,'surfaceId':sid,'kind':kind,'legacyType':bw['type'],'task':w['task'],'answerMode':w['answerMode'],'promptPreserved':bw['prompt']==w['prompt'],'variantPreserved':bstep.get('variant')==astep.get('variant'),'authoredTruthPreserved':pres})
 normalized=copy.deepcopy(after);amap={(k,i):(step,w) for k,i,step,w in surfaces(normalized)}
 for k,i,_,bw in bs:amap[(k,i)][0]['widget']=bw
 if normalized!=before:errors.append(f'{lid}: non-widget authored content drift')
changed=[]
for p in (ROOT/'content/courses').glob('*/lessons/*.json'):
 rel=p.relative_to(ROOT).as_posix();cur=hashlib.sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest()
 if S146_HASHES.get(rel)!=cur:changed.append(rel)
expected_changed={p.relative_to(ROOT).as_posix() for p in TARGETS.values()}
